/**
 * Dependency-free per-entry-point coverage gate.
 *
 * Node writes V8 function ranges for the TypeScript source files loaded by
 * jiti. The committed baseline deliberately prevents regressions without
 * pretending that a one-off global percentage is meaningful for every
 * extension.
 */
import {
  mkdtempSync,
  readFileSync,
  readdirSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { spawnSync } from "node:child_process";
import { tmpdir } from "node:os";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, "..");
const BASELINE_PATH = path.join(__dirname, "coverage-baseline.json");
const writeBaseline = process.argv.includes("--write-baseline");

/** How far above its floor a measurement may drift before the floor is stale. */
const STALE_MARGIN_POINTS = 5;

function activeExtensionPaths() {
  const settings = JSON.parse(
    readFileSync(path.join(ROOT, "settings.json"), "utf8"),
  );
  return settings.extensions
    .filter(
      (entry) => typeof entry === "string" && entry.startsWith("+extensions/"),
    )
    .map((entry) => entry.slice(1));
}

function coverageFiles(directory) {
  return readdirSync(directory)
    .filter((name) => name.endsWith(".json"))
    .map((name) => path.join(directory, name));
}

function functionCoverage(coverage, relativePath) {
  const sourceUrl = pathToFileURL(path.join(ROOT, relativePath)).href;
  const sources = coverage
    .flatMap((entry) => entry.result ?? [])
    .filter((entry) => entry.url === sourceUrl);
  if (sources.length === 0) return { covered: 0, total: 0, percent: 0 };
  const functions = new Map();
  for (const source of sources) {
    for (const fn of source.functions.filter(
      (candidate) =>
        candidate.functionName &&
        // jiti's ESM interop emits one bare `get` accessor per imported or
        // re-exported binding. They are module plumbing, not code under test,
        // and they only count as "covered" when the binding happens to be
        // dereferenced at runtime — which inflated the denominator of any file
        // with a large `export … from` block. extensions/lsp/index.ts read 20%
        // while 22 of its 30 uncovered "functions" were these accessors.
        // Source getters are safe: V8 names them `get <property>`, never `get`.
        candidate.functionName !== "get",
    )) {
      const range = fn.ranges[0];
      const key = `${fn.functionName}:${range.startOffset}:${range.endOffset}`;
      functions.set(key, Math.max(functions.get(key) ?? 0, range.count ?? 0));
    }
  }
  const covered = [...functions.values()].filter((count) => count > 0).length;
  const total = functions.size;
  return {
    covered,
    total,
    percent: total === 0 ? 100 : (covered / total) * 100,
  };
}

function collectCoverage(directory, extensions) {
  const coverage = coverageFiles(directory).map((file) =>
    JSON.parse(readFileSync(file, "utf8")),
  );
  return Object.fromEntries(
    extensions.map((extension) => [
      extension,
      functionCoverage(coverage, extension),
    ]),
  );
}

function baselineFrom(results, extensions) {
  return {
    version: 1,
    metric: "v8-function",
    activeExtensions: extensions,
    minimumFunctionCoverage: Object.fromEntries(
      extensions.map((extension) => [
        extension,
        Math.floor(results[extension].percent),
      ]),
    ),
  };
}

function printReport(results) {
  for (const [extension, value] of Object.entries(results)) {
    console.log(
      `${extension}: ${value.covered}/${value.total} functions (${value.percent.toFixed(1)}%)`,
    );
  }
}

const extensions = activeExtensionPaths();
const coverageDirectory = mkdtempSync(path.join(tmpdir(), "pi-v8-coverage-"));

try {
  const result = spawnSync(
    process.execPath,
    [path.join(__dirname, "run-all.mjs")],
    {
      cwd: ROOT,
      env: { ...process.env, NODE_V8_COVERAGE: coverageDirectory },
      stdio: "inherit",
    },
  );
  if (result.error) throw result.error;
  if (result.status !== 0) process.exitCode = result.status ?? 1;
  if (process.exitCode) process.exit(process.exitCode);

  const measurements = collectCoverage(coverageDirectory, extensions);
  printReport(measurements);
  if (writeBaseline) {
    writeFileSync(
      BASELINE_PATH,
      JSON.stringify(baselineFrom(measurements, extensions), null, 2) + "\n",
    );
    console.log(
      `Coverage baseline written: ${path.relative(ROOT, BASELINE_PATH)}`,
    );
    process.exit(0);
  }

  const baseline = JSON.parse(readFileSync(BASELINE_PATH, "utf8"));
  const expected = JSON.stringify(baseline.activeExtensions);
  const actual = JSON.stringify(extensions);
  if (
    baseline.version !== 1 ||
    baseline.metric !== "v8-function" ||
    expected !== actual
  ) {
    throw new Error(
      "Coverage baseline does not match the active extension list. Run npm run test:coverage:baseline after reviewing the changed coverage.",
    );
  }
  for (const extension of extensions) {
    const measurement = measurements[extension];
    const minimum = baseline.minimumFunctionCoverage?.[extension];
    if (!measurement || !Number.isInteger(minimum)) {
      throw new Error(
        `Coverage baseline has no valid minimum for ${extension}.`,
      );
    }
    if (measurement.total === 0) {
      throw new Error(
        `${extension} was not activated by the regression suite.`,
      );
    }
    if (measurement.percent < minimum) {
      throw new Error(
        `${extension} regressed to ${measurement.percent.toFixed(1)}%; minimum is ${minimum}%.`,
      );
    }
    // A floor written from a past measurement only stops regression. Once the
    // suite has moved well past it, the floor is a record of history rather
    // than a commitment, and the next regression can hide underneath it.
    if (measurement.percent - minimum > STALE_MARGIN_POINTS) {
      console.warn(
        `WARNING: ${extension} is at ${measurement.percent.toFixed(1)}% but its floor is ${minimum}%. Run npm run test:coverage:baseline to lock in the gain.`,
      );
    }
  }
} finally {
  rmSync(coverageDirectory, { recursive: true, force: true });
}

// P1 regression test for the locally patched Pi 0.84.1 runtime.
// It intentionally targets the executable runtime, not npm/node_modules,
// because that is the Pi instance users actually start.
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";

const RUNTIME_ROOT =
  process.env.PI_RUNTIME_ROOT ??
  "/home/d/.npm-global/lib/node_modules/@earendil-works/pi-coding-agent";

const packageJson = JSON.parse(
  readFileSync(`${RUNTIME_ROOT}/package.json`, "utf8"),
);
assert.equal(
  packageJson.version,
  "0.84.1",
  "P1 runtime patch is pinned to Pi 0.84.1",
);

const loaderSource = readFileSync(
  `${RUNTIME_ROOT}/dist/core/extensions/loader.js`,
  "utf8",
);
const runnerSource = readFileSync(
  `${RUNTIME_ROOT}/dist/core/extensions/runner.js`,
  "utf8",
);
const sessionSource = readFileSync(
  `${RUNTIME_ROOT}/dist/core/agent-session.js`,
  "utf8",
);
const packageManagerSource = readFileSync(
  `${RUNTIME_ROOT}/dist/core/package-manager.js`,
  "utf8",
);
const interactiveSource = readFileSync(
  `${RUNTIME_ROOT}/dist/modes/interactive/interactive-mode.js`,
  "utf8",
);

// Retired in 0.84.0: loader-scoped-events / loader-unsubscriber-list /
// runner-dispose / session-reload-dispose used to scope and drain extension
// event-bus listeners by hand. Upstream now does this natively — a
// generation-scoped set drained by invalidate() — so these assertions check
// that native mechanism instead of the old patch markers.
assert.match(
  loaderSource,
  /trackEventBusSubscription/,
  "loader scopes event-bus listeners to their generation",
);
assert.match(
  runnerSource,
  /invalidate\(message = [\s\S]{0,600}this\.runtime\.invalidate\(message\)/,
  "runner invalidation forwards to the generation-scoped runtime",
);
assert.match(
  sessionSource,
  /await emitSessionShutdownEvent[\s\S]{0,240}oldRunner\.invalidate\(\)/,
  "reload invalidates the replaced runner",
);
assert.match(
  packageManagerSource,
  /applyConfiguredExtensionOrder/,
  "package manager honors explicit extension order",
);
assert.match(
  sessionSource,
  /const builtinCommands = BUILTIN_SLASH_COMMANDS\.map/,
  "command inventory includes Pi built-ins",
);
assert.match(
  interactiveSource,
  /submitSlashCommand: async \(commandLine\)/,
  "interactive UI exposes canonical slash submission",
);
assert.match(
  interactiveSource,
  /onTerminalInput: \(handler\) => this\.addExtensionTerminalInputListener\(\(data\) => this\.ui\.focusedComponent === this\.editor \? handler\(data\) : undefined\)/,
  "extension terminal listeners yield to focused selectors and overlays",
);
assert.match(
  interactiveSource,
  /onExtensionShortcut = \(data\) => \{[\s\S]{0,900}Promise\.resolve\(shortcut\.handler\(createContext\(\)\)\)\.catch/,
  "extension shortcuts launch without awaiting the handler on the input path",
);
assert.match(
  interactiveSource,
  /addChild\(this\.extensionSelector\);[\s\S]{0,120}setFocus\(this\.extensionSelector\)/,
  "native extension selectors explicitly take keyboard focus",
);
assert.match(
  interactiveSource,
  /hideExtensionSelector\(\) \{[\s\S]{0,260}setFocus\(this\.editor\)/,
  "closing a native extension selector restores editor focus",
);

const { createEventBus } = await import(
  `${RUNTIME_ROOT}/dist/core/event-bus.js`
);
const { createExtensionRuntime, loadExtensionFromFactory } = await import(
  `${RUNTIME_ROOT}/dist/core/extensions/loader.js`
);
const { ExtensionRunner } = await import(
  `${RUNTIME_ROOT}/dist/core/extensions/runner.js`
);

const eventBus = createEventBus();
let generation = 0;
let activeRunner;

for (let reload = 1; reload <= 10; reload += 1) {
  activeRunner?.invalidate();
  const runtime = createExtensionRuntime();
  const instance = ++generation;
  const extension = await loadExtensionFromFactory(
    (pi) => {
      pi.events.on("p1:reload-provider", (event) => {
        event.respond(instance);
      });
    },
    process.cwd(),
    eventBus,
    runtime,
    `<p1-reload-${reload}>`,
  );
  activeRunner = new ExtensionRunner(
    [extension],
    runtime,
    process.cwd(),
    {},
    {},
  );

  const responses = [];
  eventBus.emit("p1:reload-provider", {
    respond(value) {
      responses.push(value);
    },
  });
  await new Promise((resolve) => setImmediate(resolve));
  assert.deepEqual(
    responses,
    [instance],
    `reload ${reload} has exactly one current event-bus provider`,
  );
}

activeRunner.invalidate();
const postInvalidateResponses = [];
eventBus.emit("p1:reload-provider", {
  respond(value) {
    postInvalidateResponses.push(value);
  },
});
await new Promise((resolve) => setImmediate(resolve));
assert.deepEqual(
  postInvalidateResponses,
  [],
  "invalidating the last runner removes its listener",
);

console.log("P1 runtime reload regression passed.");

