            "tool_execution_start",
            {
              toolCallId: "foreground-subagent",
              toolName: "subagent",
              args: { agent: "worker" },
            },
            widgetContext,
          );
          assert(
            render().includes("worker"),
            "a running foreground subagent appears straight from the tool call",
          );

