    getAllTools() {
      if (Array.isArray(options.registeredTools))
        return options.registeredTools;
      return [...tools.values()].map((tool) => ({
        name: tool.name,
        description: tool.description,
        parameters: tool.parameters,
        promptGuidelines: tool.promptGuidelines,
        sourceInfo: {
          path: "<test>",
          source: "test",
          scope: "temporary",
          origin: "top-level",
        },
      }));
    },
  };

  return {
    api,
    hooks,
    commands,
    commandDescriptions,
    shortcuts,
    tools,
    duplicateTools,
    statusCalls,
    statuses,
    notifications,
    emitted,
    appended,
    sent,
    customComponents,
    entryRenderers,
    theme,
    chrome,
    workingMessages,
    workingVisibility,
    workingIndicators,
    hiddenThinkingLabels,
    execCalls,
    setModelCalls,
    submittedCommands,
    widgets,
    lifecycleCalls,
    setIdle(value) {
      idle = value;
    },
    dispatchShortcut(shortcut, context) {
      const handler = shortcuts.get(shortcut);
      if (!handler)
        return { handled: false, completion: Promise.resolve(undefined) };
      let result;
      try {
        result = handler(context);
      } catch (error) {
        result = Promise.reject(error);
      }
      const completion = Promise.resolve(result).catch((error) => {
        notifications.push({
          message: `Shortcut handler error: ${error instanceof Error ? error.message : String(error)}`,
          level: "error",
        });
      });
      return { handled: true, completion };
    },
    setFocusedComponent(component) {
      focusStack.length = 0;
      if (component) focusStack.push(component);
    },
    sendTerminalInput(data) {
      let current = data;
      const focused = focusStack.at(-1);
      // The patched Pi runtime scopes extension terminal listeners to editor
      // focus so they cannot preempt a selector or custom overlay.
      if (!focused) {
        for (const listener of [...terminalInputListeners]) {
          const result = listener(current);
          if (result?.consume) return { consumed: true, data: current };
          if (result?.data !== undefined) current = result.data;
        }
      }
      if (current.length > 0 && typeof focused?.handleInput === "function") {
        focused.handleInput(current);
        return { consumed: true, data: current };
      }
      return { consumed: current.length === 0, data: current };
    },
    get focusedComponent() {
      return focusStack.at(-1);
    },
    get terminalInputListenerCount() {
      return terminalInputListeners.size;
    },
    get footerFactory() {
      return footerFactory;
    },
    get branchReads() {
      return branchReads;
    },
    emitBranchChange() {
      for (const listener of branchListeners) listener();
    },
    get editorFactory() {
      return editorFactory;
    },
    get editorText() {
      return editorText;
    },
    makeContext({
      cwd = ROOT,
      mode = "tui",
      hasUI = mode === "tui",
      sessionId = options.sessionId ?? "test-session",
