import { truncateToWidth, visibleWidth } from "@earendil-works/pi-tui";

/**
 * Pure, terminal-cell-safe display form for the session cwd.
 *
 * The caller supplies both paths from session state, so this helper never
 * resolves paths or touches the filesystem. It favors a home-relative full
 * path first, then an ellipsized path that retains the final directory.
 */
export function compactCwd(
  cwd: string,
  maxColumns: number,
  homeDirectory?: string,
): string {
  const available = Math.max(1, Math.floor(maxColumns));
  const home = homeDirectory?.replace(/\/+$/, "");
  const normalized = cwd || "/";
  const withinHome = Boolean(
    home && (normalized === home || normalized.startsWith(`${home}/`)),
  );
  const display = withinHome
    ? normalized === home
      ? "~"
      : `~${normalized.slice(home!.length)}`
    : normalized;

  if (visibleWidth(display) <= available) return display;

  const parts = display.split("/").filter(Boolean);
  const leaf = parts.at(-1) ?? display;
  const rooted = display.startsWith("/");
  const prefix = display.startsWith("~") ? "~" : rooted ? "/" : "";
  const ellipsized = prefix
    ? `${prefix}/…/${leaf}`
    : `…/${leaf}`;
  if (visibleWidth(ellipsized) <= available) return ellipsized;

  const short = prefix ? `${prefix}/${leaf}` : leaf;
  if (visibleWidth(short) <= available) return short;
  return truncateToWidth(leaf, available, "…");
}

import type { Theme } from "@earendil-works/pi-coding-agent";
import { truncateToWidth, visibleWidth } from "@earendil-works/pi-tui";
import { layoutForSize } from "../shared/layout.ts";
import { compactCwd } from "./cwd.ts";
import { renderThinkingLabel } from "./thinking.ts";

export interface StartscreenInput {
  width: number;
  rows: number;
  workflow: string;
  model?: string;
  thinking?: string;
  cwd: string;
  homeDirectory?: string;
}

const WORDMARK = [
  " █████╗ ██╗   ██╗██████╗  ██████╗ ██████╗ ",
  "██╔══██╗██║   ██║██╔══██╗██╔═══██╗██╔══██╗",
  "███████║██║   ██║██████╔╝██║   ██║██████╔╝",
  "██╔══██║██║   ██║██╔══██╗██║   ██║██╔══██╗ ",
  "██║  ██║╚██████╔╝██║  ██║╚██████╔╝██║  ██║ ",
];

function center(value: string, width: number): string {
  const clipped = truncateToWidth(value, Math.max(1, width), "…");
  return `${" ".repeat(Math.max(0, Math.floor((width - visibleWidth(clipped)) / 2)))}${clipped}`;
}

function separator(theme: Theme): string {
  return theme.fg("borderMuted", " │ ");
}

function metadata(theme: Theme, input: StartscreenInput, width: number): string {
  const model = truncateToWidth(input.model ?? "kein Modell", 28, "…");
  const values = [
    theme.fg("accent", theme.bold(input.workflow.toUpperCase())),
    theme.fg("text", model),
  ];
  if (input.thinking) values.push(renderThinkingLabel(theme, input.thinking));
  return center(values.join(separator(theme)), width);
}

/**
 * A fresh-session welcome only. Its caller owns whether the session is still
 * fresh; this function only formats values that session state already has.
 */
export function renderStartscreen(
  theme: Theme,
  input: StartscreenInput,
): string[] {
  const width = Math.max(1, input.width);
  const layout = layoutForSize(width, input.rows);
  const cwd = compactCwd(
    input.cwd,
    layout === "compact" ? 20 : layout === "standard" ? 34 : 48,
    input.homeDirectory,
  );
  const folder = center(theme.fg("muted", cwd), width);

  if (layout === "compact")
    return [
      center(theme.fg("accent", theme.bold("PI · AURORA")), width),
      metadata(theme, input, width),
      folder,
    ];

  const shortcuts = [
    "Shift+Tab  Workflow",
    "Super+M    Model",
    "Super+D    Thinking",
    "Super+Q    Command Center",
  ].map((line) => center(theme.fg("dim", line), width));

  if (layout === "standard")
    return [
      center(theme.fg("accent", theme.bold("PI · AURORA")), width),
      "",
      metadata(theme, input, width),
      folder,
      "",
      ...shortcuts,
    ];

  return [
    ...WORDMARK.map((line) => center(theme.fg("border", line), width)),
    center(theme.fg("accent", theme.bold("A U R O R A")), width),
    "",
    metadata(theme, input, width),
    folder,
    "",
    ...shortcuts,
  ];
}

import type { Theme } from "@earendil-works/pi-coding-agent";

export type ThinkingTone =
  | "thinkingOff"
  | "thinkingMinimal"
  | "thinkingLow"
  | "thinkingMedium"
  | "thinkingHigh"
  | "thinkingXhigh";

const TONE_BY_LEVEL: Record<string, ThinkingTone> = {
  off: "thinkingOff",
  minimal: "thinkingMinimal",
  low: "thinkingLow",
  medium: "thinkingMedium",
  high: "thinkingHigh",
  xhigh: "thinkingXhigh",
};

/** The configured thinking level is display-only; unknown values stay muted. */
export function thinkingTone(level: string | undefined): ThinkingTone | "muted" {
  return TONE_BY_LEVEL[level?.toLowerCase() ?? ""] ?? "muted";
}

export function thinkingLabel(level: string | undefined): string {
  return (level || "off").toUpperCase();
}

export function renderThinkingLabel(
  theme: Theme,
  level: string | undefined,
): string {
  return theme.fg(thinkingTone(level), thinkingLabel(level));
}

